import { cacheTag } from 'next/cache'

export type Post = {
  id: number
  title: string
  createdAt: number
}

// In-memory store. Persists for the lifetime of the running server process,
// which is enough to demonstrate cache-tag invalidation.
const posts: Post[] = [
  { id: 1, title: 'Welcome to the blog', createdAt: 0 },
  { id: 2, title: 'Understanding Next.js caching', createdAt: 0 },
]
let nextId = posts.length + 1

export async function addPost(title: string): Promise<Post> {
  const post: Post = { id: nextId++, title, createdAt: Date.now() }
  posts.push(post)
  return post
}

// The posts list is cached and tagged with "posts" so it can be invalidated
// on-demand when a new post is created.
export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheTag('posts')
  return posts.map((post) => ({ ...post }))
}

